(function(){
  'use strict';
  const E=window.HZLML;
  let learned=null,useML=false,labError='',pendingRows=null;
  let stress={scope:'Domestic',demand:-5,premium:10,delay:7,duration:2};
  let peers=[{name:'HZL planning case',premium:160,freight:0,depot:14.29,grade:'SHG zinc',basis:'India west / delivered',credit:30,lead:5},{name:'Global peer A · sample',premium:150,freight:22,depot:8,grade:'SHG zinc',basis:'India west / delivered',credit:30,lead:19},{name:'Global peer B · sample',premium:140,freight:20,depot:9,grade:'SHG zinc',basis:'India west / delivered',credit:30,lead:24}];
  const baseModel=model,baseChart=chart,baseForecast=forecast,basePricing=pricing,baseOverview=overview,baseSource=sourceView,baseRender=render,baseExport=$('#export').onclick,baseSpec=spec;
  const monthLabel=s=>new Date(s+'-01T00:00:00Z').toLocaleDateString('en-GB',{month:'short',year:'numeric',timeZone:'UTC'});
  const metricsValue=(v,d=1)=>v===null?'—':fmt(v,d);
  function selection(){
    const g=learned?.groups[metal()];if(!g)return null;
    const wanted=months().map(m=>{const [mon,year]=m.split(' ');return year+'-'+String(['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'].indexOf(mon)+1).padStart(2,'0')});
    const forecast=wanted.map(s=>g.forecasts.find(f=>f.month===s));
    return forecast.every(Boolean)?{g,forecast}:null;
  }
  const label=()=>learned?.classification||'No trained model';
  function modelNotice(){return `<div class="notice"><div><strong>Learned forecast · ${esc(label())}</strong><p>Aggregate ${metal()} model; latest closed observation ${esc(monthLabel(learned.groups[metal()].lastMonth))}. Customer wallet, capacity and shipment records elsewhere remain separate sample inputs. Prediction intervals are not calibrated and this model has no production approval.</p></div></div>`}
  model=function(){
    const original=baseModel(),s=useML&&selection();if(!s)return original;
    const forecast=s.forecast.map(r=>({month:monthLabel(r.month),point:Math.round(r.order_tonnes),low:null,high:null,booked:null,source:'ML pilot'}));
    return {...original,forecast,total:forecast.reduce((a,r)=>a+r.point,0),learned:true};
  };
  function forecastTable(rows){return table(['Month','Demand forecast (t)','Premium forecast (USD/t)','Premium direction','Interval'],rows.map(r=>[monthLabel(r.month),fmt(r.order_tonnes),fmt(r.premium_usd_t,1),r.premiumDirection,'Not calibrated']))}
  chart=function(){
    const s=useML&&selection();if(!s)return baseChart();
    const observed=s.g.rows.slice(-3).map(r=>({month:r.month,value:r.order_tonnes})),predicted=s.forecast.map(r=>({month:r.month,value:r.order_tonnes})),all=[...observed,...predicted];
    const min=E.monthIndex(all[0].month),max=E.monthIndex(all.at(-1).month),top=Math.max(1,...all.map(r=>r.value))*1.18;
    const x=r=>48+490*(E.monthIndex(r.month)-min)/Math.max(1,max-min),y=r=>205-165*r.value/top;
    return `<svg class="chart" viewBox="0 0 570 255" role="img" aria-label="Imported aggregate demand history and trained monthly forecasts">${[0,.5,1].map(t=>`<line x1="48" x2="550" y1="${205-165*t}" y2="${205-165*t}" stroke="#e7eee5"/><text x="1" y="${210-165*t}">${fmt(top*t/1000,0)}k</text>`).join('')}<polyline points="${observed.map(r=>x(r)+','+y(r)).join(' ')}" fill="none" stroke="#267451" stroke-width="3"/><polyline points="${[observed.at(-1),...predicted].map(r=>x(r)+','+y(r)).join(' ')}" fill="none" stroke="#267451" stroke-width="3" stroke-dasharray="5 5"/>${all.map(r=>`<circle cx="${x(r)}" cy="${y(r)}" r="4" fill="#267451"/><text x="${x(r)-14}" y="230">${monthLabel(r.month).slice(0,3)}</text>`).join('')}</svg><p class="mini">Solid: supplied monthly history. Dashed: ML point forecasts. Calendar spacing is preserved; unselected months are not plotted. No confidence band is claimed.</p>`;
  };
  overview=function(){
    if(!useML||!selection())return baseOverview()+card('From scenarios to learned forecasts','New: train and assess the demand and premium pilot',`<p>Use historical monthly data to fit separate models and compare them with a seasonal baseline. Review market shocks and comparable peer offers in the new workspaces.</p><div class="download"><button data-v2="open-lab">Open ML lab →</button><button class="secondary" data-v2="open-signals">Market signals & peers →</button></div>`);
    const m=model(),s=selection(),metrics=s.g.metrics.filter(r=>r.target==='order_tonnes'&&s.forecast.some(f=>f.horizon===r.horizon));
    return modelNotice()+`<div class="kpis">${kpi('Selected 3-month learned demand',fmt(m.total/1000,1),'kt',label())}${kpi('First forecast month · '+m.forecast[0].month,fmt(m.forecast[0].point/1000,1),'kt','Aggregate orders · not booked volume')}${kpi('Held-out demand WAPE',fmt(metrics.reduce((a,r)=>a+r.wape,0)/metrics.length,1),'%','Mean of selected-horizon WAPE; lower is better')}${kpi('Production acceptance','Pending','','No calibrated confidence claim')}</div><div class="grid">${card('Demand history & learned outlook','Selected forecast horizon · '+metal(),chart())}${card('Monthly premium outlook','Direction versus latest observed premium; ±USD 5/t is flat',table(['Month','USD/t','Direction'],s.forecast.map(r=>[monthLabel(r.month),fmt(r.premium_usd_t,1),r.premiumDirection]))+'<button class="link" data-page="pricing">Open premium workbench →</button>')}</div>${card('Decision boundaries','Keep learned predictions separate from operating constraints',`<p>Review model performance in the ML lab. Domestic/export capacity is still an editable assumption; customer share of wallet uses separate sample customer records. Neither is automatically optimized or inferred from this aggregate training file.</p><button data-v2="open-lab">Review model evidence →</button>`)}`;
  };
  forecast=function(){
    if(!useML||!selection())return baseForecast()+card('Train against historical outcomes','A working supervised model is now available in the ML lab',`<p>The existing scenario remains transparent and manual. The lab learns coefficients from monthly history and evaluates previously unseen months.</p><button data-v2="open-lab">Train / review a model →</button>`);
    const s=selection();return modelNotice()+card('Selected monthly demand & premium forecasts','Bookings and prediction intervals are unavailable from this input schema',chart()+forecastTable(s.forecast))+card('Model operating mode','Switch back to the original assumptions whenever needed',`<button data-v2="disable-ml">Use manual scenario instead</button><button class="secondary" data-v2="open-lab">Backtests & model card</button>`);
  };
  pricing=function(){const g=learned?.groups[metal()];return basePricing()+card('Learned premium direction','Separate supervised target; not an automatic auction starting premium',g?`<p class="mini">${esc(label())}. Direction is relative to the last observed premium of USD ${fmt(g.rows.at(-1).premium_usd_t,1)}/t. ±USD 5/t is classified as flat.</p>`+forecastTable(selection()?.forecast||g.forecasts.slice(0,3))+`<p>Review normalized offers, demand and auction history before choosing a starting premium. The predicted premium is a statistical reference, not an approved pricing recommendation.</p>`:`<div class="empty">No premium model trained.</div><button data-v2="open-lab">Train on historical premiums →</button>`)+card('Global-player comparison','Normalize grade, location, delivery terms and credit before comparing offers',`<button data-v2="open-signals">Open comparable-offer workbench →</button>`)};
  function lab(){
    const g=learned?.groups[metal()];
    let result='<div class="empty">No model has been trained in this session. Load the synthetic demonstration or import an approved aggregate history file.</div>';
    if(g){
      const results=g.metrics;
      result=`<div class="notice"><div><strong>${esc(label())} · candidate model only</strong><p>Separate standardized ridge models are fitted for demand and premium at horizons 1–6. Inputs and fitted scaling use only information available at each forecast origin. Client acceptance is not established.</p></div></div><div class="kpis">${kpi('History coverage',g.rows.length,'months',monthLabel(g.rows[0].month)+'–'+monthLabel(g.lastMonth))}${kpi('Forecast horizons','1–6','months','Supports rolling and next-quarter views')}${kpi('Backtest design','Rolling','','Up to 12 chronological origins per horizon')}${kpi('Prediction interval','Unavailable','','No 90% coverage claim')}</div>`+
      card('Demand validation against a seasonal baseline','WAPE = sum of absolute error ÷ sum of actual volume; lower is better',table(['Horizon','Tests','ML WAPE','Baseline WAPE','Bias','Within ±10%'],results.filter(r=>r.target==='order_tonnes').map(r=>[r.horizon+' month(s)',r.n,metricsValue(r.wape)+'%',metricsValue(r.baselineWape)+'%',metricsValue(r.bias)+'%',fmt(r.within10,1)+'%']))+`<p class="mini">“Within ±10%” is a proposed tolerance, not the client's agreed definition of above-90% confidence. Synthetic scores demonstrate mechanics only; uploaded scores remain unverified. Seasonal baseline uses the same month last year, known at each origin.</p>`)+
      card('Premium validation','USD/t errors and direction relative to premium at the forecast origin',table(['Horizon','Tests','ML MAE USD/t','ML WAPE','Baseline WAPE','Direction accuracy'],results.filter(r=>r.target==='premium_usd_t').map(r=>[r.horizon+' month(s)',r.n,fmt(r.mae,1),metricsValue(r.wape)+'%',metricsValue(r.baselineWape)+'%',fmt(r.directionAccuracy,1)+'%']))+'<p class="mini">Direction uses a USD 5/t flat band. A model that performs worse than baseline should not be promoted.</p>')+
      card('Forecasts from the latest closed month','Targets are monthly aggregate orders and comparable premium; no shipment forecasts are claimed',forecastTable(g.forecasts))+
      card('Model evidence & operating mode','Model weights and metrics can be inspected and exported',`<ul class="metric-list"><li><strong>Algorithm:</strong> ridge regression, fixed alpha = 10, training-fold standardization, separate direct model per target and horizon. No automatic tuning on the evaluation months.</li><li><strong>Features:</strong> order lags and rolling mean, latest premium, imports, LME, FX, sector index, domestic/global risk, and target-month seasonality. Exogenous inputs come from the origin snapshot; future realized prices or news are not used.</li><li><strong>Leading h=1 demand associations:</strong> ${g.modelCards.find(r=>r.target==='order_tonnes'&&r.horizon===1).contributions.slice(0,4).map(r=>esc(r.feature)).join(', ')}. Coefficients describe model associations, not causal effects.</li><li><strong>Release gate:</strong> verify original snapshot availability and coverage, agree tolerance, evaluate more origins and segments, calibrate prediction intervals, review drift, and obtain human sign-off. ${g.metrics.some(r=>r.wape>r.baselineWape)?'At least one model/horizon loses to the baseline in this run.':''}</li></ul><div class="download"><button data-v2="enable-ml" ${selection()?'':'disabled'}>Use in selected dashboard horizon</button><button class="secondary" data-v2="export-model">Download model card</button><button class="secondary" data-v2="clear-ml">Clear in-memory model</button></div>${selection()?'':'<p class="warning">Selected calendar horizon is outside this model’s six-month range or selected metal is absent. Choose a covered horizon / metal.</p>'}`);
    }
    return card('Trainable forecasting pilot','This is working browser-side supervised ML; it is not a production forecasting service',`<div class="download"><button data-v2="train-synthetic">Train synthetic demonstration</button><button class="secondary" data-v2="template">Download example CSV</button></div><div class="form-grid"><div class="field"><label for="history-file">Import approved aggregate monthly history (CSV, ≤2 MB)</label><input id="history-file" type="file" accept=".csv,text/csv"></div></div><p class="mini">Files are processed in browser memory and are not uploaded or saved to local storage by this pilot. Use aggregate, authorized data; no customer identifiers are required. Publication on Vercel does not give this app access to ERP, market subscriptions or vessel data.</p><p id="lab-status" role="status">${esc(labError)}</p><button data-v2="train-upload" ${pendingRows?'':'disabled'}>Validate & train imported history</button><details><summary>CSV contract and publication-date handling</summary><p>Required headers: <code>${E.columns.join(', ')}</code>. One row per metal/month, at least 36 consecutive closed months per included metal. Supply comparable USD/t premiums and tonnes. <code>known_at</code> must be a valid date within the row's month and no later than 23 Oct 2026. Only history through Sep 2026 is accepted. Each feature row is an origin snapshot: align delayed trade releases to when they became available, not the period they describe. These date checks cannot independently authenticate source or revision history.</p></details>`)+result;
  }
  function signals(){
    const m=model(),g=learned?.groups[metal()],p=selection()?.forecast?.[0]?.premium_usd_t??settings.premium;
    const impacts=m.forecast.map((r,i)=>({month:r.month,base:r.point,stressed:Math.max(0,Math.round(r.point*(1+(i<stress.duration?stress.demand/100:0))))}));
    const shifted=shipments.filter(r=>r[1]===metal()).map(r=>{const dt=new Date(r[5]+' UTC');dt.setUTCDate(dt.getUTCDate()+stress.delay);return [r[0],r[2],r[5],dt.toLocaleDateString('en-GB',{timeZone:'UTC'}),fmt(r[4])]});
    return `<div class="notice"><div><strong>Domestic & global event scenarios</strong><p>The transcript asks how domestic and global crises could affect orders. Quantified effects here are user-supplied assumptions, not news-derived causal predictions. No current event is asserted.</p></div></div>`+
      card('Stress the order book and premium','Apply an assumed shock without changing the original forecast',`<div class="form-grid"><div class="field"><label for="event-scope">Event scope</label><select id="event-scope"><option ${stress.scope==='Domestic'?'selected':''}>Domestic</option><option ${stress.scope==='Global'?'selected':''}>Global</option></select></div><div class="field"><label for="event-demand">Demand impact (%)</label><input id="event-demand" type="number" min="-50" max="50" step=".5" value="${stress.demand}"></div><div class="field"><label for="event-premium">Premium impact (USD/t)</label><input id="event-premium" type="number" min="-200" max="200" value="${stress.premium}"></div><div class="field"><label for="event-delay">Shipment delay (days)</label><input id="event-delay" type="number" min="0" max="90" value="${stress.delay}"></div><div class="field"><label for="event-duration">Affected forecast months</label><select id="event-duration">${[1,2,3].map(v=>`<option ${v===stress.duration?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="download"><button data-v2="apply-stress">Apply event assumptions</button><button class="secondary" data-v2="reset-stress">Reset assumptions</button></div><p class="mini">Scope is an annotation; the percentage is applied uniformly to the first selected N forecast months. Sector exposure, substitution and causal event effects are not estimated.</p>`)+
      card('Baseline versus event case',`${esc(stress.scope)} scenario · ${m.learned?esc(label()):'manual sample baseline'}`,table(['Month','Baseline orders (t)','Event case (t)','Difference'],impacts.map(r=>[r.month,fmt(r.base),fmt(r.stressed),fmt(r.stressed-r.base)]))+`<div class="result">First-month premium reference: USD ${fmt(p,1)}/t → event case USD ${fmt(Math.max(0,+p+stress.premium),1)}/t. This is a manual sensitivity, not a recommended auction premium.</div>`)+
      card('Shipment timing sensitivity','Sample arrival dates shifted by the assumed delay; quantities are unchanged',table(['Shipment','Origin','Original sample ETA','Delayed ETA','Tonnes'],shifted))+
      card('Comparable global-player offers','Synthetic zinc offers for one grade, destination, delivery basis, credit and quote date; not actual competitor quotes',metal()==='Lead'?'<div class="empty">No comparable lead offers loaded. Do not reuse zinc offers as lead benchmarks.</div>':`<div class="table-wrap"><table><thead><tr><th>Entity</th><th>Premium USD/t</th><th>Incremental freight USD/t</th><th>Depot USD/t</th><th>Delivered premium</th><th>Gap to HZL</th></tr></thead><tbody>${peers.map((r,i)=>`<tr><td>${esc(r.name)}</td>${['premium','freight','depot'].map(k=>`<td><input aria-label="${esc(r.name+' '+k)}" data-peer-index="${i}" data-peer-field="${k}" type="number" min="0" max="2000" step=".01" value="${r[k]}" style="width:90px"></td>`).join('')}<td>${fmt(r.premium+r.freight+r.depot,2)}</td><td>${fmt(r.premium+r.freight+r.depot-(peers[0].premium+peers[0].freight+peers[0].depot),2)}</td></tr>`).join('')}</tbody></table></div><p class="mini">All sample rows: SHG zinc; India west coast / delivered basis; 30-day credit; 23 Oct 2026. Delivered premium = premium + incremental freight + depot cost in USD/t. Freight must not already be embedded in quoted premium. LME is excluded from this premium-only comparison; real quotes require date, grade, Incoterm, destination, FX and credit normalization.</p><button data-v2="apply-peers">Recalculate comparable offers</button>`);
  }
  const coverage=[
    ['Single demand / premium / allocation dashboard','1:14–1:35','Integrated views; trained forecasts can be selected','Pilot; live data and allocation optimization pending'],
    ['Monthly order book for next quarter; >90% confidence','2:03–2:18','Rolling / calendar-quarter horizon and ML backtests','Acceptance definition and calibrated intervals pending'],
    ['Global metal movement and outlook','0:35–0:55','Shipment radar and scenario arrival shifts','Live licensed tracking / forecast service pending'],
    ['HZL versus global players','0:55','Comparable-offer workbench','Synthetic offers; actual normalized quotes required'],
    ['Domestic / global crisis effects','1:14–1:35','Explicit order, premium and timing stress tests','User assumptions; no causal model or live news feed'],
    ['Country trade websites and fragmented imports','0:16','Source register and availability-aware CSV contract','Automated ingestion / reconciliation pending'],
    ['Fastmarkets and Wood Mackenzie reports','0:35','Both represented in source planning','No account or license connection implied'],
    ['In-house or third-party delivery','15:14–15:56','Delivery checklist and implementation roadmap','Actual staffing / vendor engagement required'],
    ['Partner access after onboarding and PO','15:38','Checklist records both prerequisites','Production access controls / secure sharing pending'],
    ['Earlier vendor avenue is unhelpful','17:01–17:20','Legacy-source replacement action recorded','Exact identity retained in private review; meeting report not independently verified']
  ];
  sourceView=function(){return baseSource()+card('Transcript requirement review','Supplied excerpt reviewed; it jumps from 2:21 to 15:14',table(['Requirement','Meeting time','Implemented','Remaining gap'],coverage))+card('Production architecture','ML is one service within a governed operating system',`<div class="steps"><div class="step"><strong>Licensed source ingestion & reconciliation</strong><p>ERP/CRM, customer demand, auction history, trade releases, cargo/vessel events, market prices and dated sector/news signals. Store original publication dates, revisions, units and product identifiers.</p></div><div class="step"><strong>Warehouse, features and prediction services</strong><p>Versioned datasets; models for customer demand, aggregate orders, shipment arrivals and premium; calibrated intervals, baselines, explanations, drift and failure monitoring.</p></div><div class="step"><strong>Decision services & controlled access</strong><p>Approved parity formula, normalized offers and allocation optimizer subject to commitments and capacity; SSO, roles, audit records and human overrides.</p></div><div class="step"><strong>Client acceptance & rollout</strong><p>Agree success criteria, run a scoped pilot, measure performance and operational benefit, then roll out. Browser ML and manual scenarios do not satisfy the complete production contract.</p></div></div>`)};
  spec=function(){return baseSpec()+`\n## New forecasting pilot\nThe browser ML lab trains separate ridge-regression models for aggregate monthly demand and premium at horizons 1–6. CSV inputs: ${E.columns.join(', ')}. At least 36 consecutive closed monthly snapshots per metal are required. Alpha is fixed at 10; means/scales are fitted within each training fold. Rolling-origin backtests compare forecasts with the same month last year. WAPE, signed bias, absolute premium error, proposed +/-10% tolerance and premium direction are reported. Prediction intervals are not calibrated.\n\nData stays in session memory. Synthetic demonstration scores are not HZL performance. Uploaded data is unverified. A model may be selected for matching dashboard months; customer wallet, shipments and capacity remain separate sample inputs. Manual crisis assumptions and synthetic normalized peer offers are available in Market signals and peers. These do not estimate causal event effects or replace licensed feeds.\n\nProduction still requires authenticated server storage, publication-date source snapshots, ingestion, scheduled forecasts, shipment-arrival models, normalized quote data, calibrated intervals, monitoring, allocation optimization, governance and acceptance testing.\n`};
  pages.splice(pages.length-1,0,['signals','⌘','Market signals & peers'],['ml','∿','ML lab & validation']);
  function exportModel(){
    const safe={...learned,groups:Object.fromEntries(Object.entries(learned.groups).map(([key,g])=>[key,{metal:g.metal,lastMonth:g.lastMonth,historyMonths:g.rows.length,forecasts:g.forecasts,metrics:g.metrics,modelCards:g.modelCards}]))};
    download('HZL-model-card.json',JSON.stringify(safe,null,2),'application/json');
  }
  function trainRows(rows,classification){try{labError='';learned=E.train(rows,{classification});useML=false;render()}catch(error){labError=error.message;render()}}
  function bindV2(){
    document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>location.hash=el.dataset.page);
    document.querySelectorAll('[data-v2]').forEach(el=>el.onclick=()=>{
      const a=el.dataset.v2;
      if(a==='open-lab')location.hash='ml';
      if(a==='open-signals')location.hash='signals';
      if(a==='train-synthetic')trainRows(E.synthetic(),'Synthetic demonstration');
      if(a==='template')download('HZL-synthetic-history.csv',E.csv(E.synthetic()),'text/csv');
      if(a==='train-upload'&&pendingRows)trainRows(pendingRows,'Uploaded aggregate history / unverified');
      if(a==='enable-ml'&&selection()){useML=true;location.hash='overview';render()}
      if(a==='disable-ml'){useML=false;render()}
      if(a==='clear-ml'){learned=null;useML=false;pendingRows=null;labError='';render()}
      if(a==='export-model'&&learned)exportModel();
      if(a==='apply-stress'){
        const ids=['event-demand','event-premium','event-delay'];for(const id of ids)if(!$('#'+id).checkValidity()||$('#'+id).value===''){$('#'+id).reportValidity();return}
        stress={scope:$('#event-scope').value,demand:+$('#event-demand').value,premium:+$('#event-premium').value,delay:+$('#event-delay').value,duration:+$('#event-duration').value};render();
      }
      if(a==='reset-stress'){stress={scope:'Domestic',demand:-5,premium:10,delay:7,duration:2};render()}
      if(a==='apply-peers'){
        const next=peers.map(r=>({...r}));for(const input of document.querySelectorAll('[data-peer-index]')){if(!input.checkValidity()||input.value===''){input.reportValidity();return}next[+input.dataset.peerIndex][input.dataset.peerField]=+input.value}peers=next;render();
      }
    });
    if($('#history-file'))$('#history-file').onchange=async event=>{
      const f=event.target.files[0];if(!f)return;
      try{if(f.size>2000000)throw Error('CSV exceeds 2 MB.');pendingRows=E.validate(E.parseCSV(await f.text()));labError='Validated '+pendingRows.length+' observations in memory. Select Validate & train to fit the models.'}catch(error){pendingRows=null;labError=error.message}render();
    };
  }
  render=function(){
    const route=location.hash.slice(1)||'overview';
    if(useML&&!selection())useML=false;
    if(['ml','signals'].includes(route)){
      current=route;const p=pages.find(r=>r[0]===route);
      $('#nav').innerHTML=pages.map(p=>`<a href="#${p[0]}" class="${p[0]===route?'active':''}"><span>${p[1]}</span>${p[2]}</a>`).join('');
      $('#title').textContent=p[2];$('#crumb').textContent='Commercial intelligence / '+p[2];$('#subtitle').textContent=route==='ml'?'Learn from history. Compare against a baseline. Validate before release.':'Explore domestic/global shocks and comparable market offers.';
      $('#view').innerHTML=route==='ml'?lab():signals();
    }else baseRender();
    bindV2();
    $('.demo').textContent=useML?'ML PILOT · '+(label().startsWith('Synthetic')?'SYNTHETIC':'UNVERIFIED'):'SAMPLE DATA';
    document.querySelector('footer span').textContent=useML?'Trained browser ML pilot · independent production validation pending':'Manual scenarios and sample records · live data not connected';
  };
  $('#metal').onchange=render;$('#horizon').onchange=render;window.onhashchange=render;
  $('#export').onclick=()=>{
    if(current==='ml'){if(learned)exportModel();else download('HZL-synthetic-history.csv',E.csv(E.synthetic()),'text/csv');return}
    if(current==='signals'){download('HZL-event-scenario.json',JSON.stringify({classification:'Manual assumptions on '+(useML?label():'sample baseline'),metal:metal(),stress,baseline:model().forecast,peerOffers:metal()==='Zinc'?peers:[]},null,2),'application/json');return}
    if(current==='pricing'&&learned?.groups[metal()]){download('HZL-pricing-and-model.json',JSON.stringify({metal:metal(),classification:label(),manualParityInputs:{lme:settings.lme,premium:settings.premium,fx:settings.fx,freight:settings.freight,depot:settings.depot,duty:settings.duty,auctionStartingPremium:settings.auction},learnedPremiumForecasts:selection()?.forecast||learned.groups[metal()].forecasts.slice(0,3),interval:'Not calibrated',auctionRecommendation:'Human review required; no automated recommendation'},null,2),'application/json');return}
    if(useML&&['overview','forecast'].includes(current)){download('HZL-learned-forecast.csv','Classification,'+label()+'\nMonth,Demand tonnes,Premium USD per tonne,Direction,Interval\n'+selection().forecast.map(r=>[r.month,r.order_tonnes,r.premium_usd_t,r.premiumDirection,'Not calibrated'].join(',')).join('\n'),'text/csv');return}
    baseExport();
  };
  render();
})();
